# Fix Proposal B: Comprehensive security fix
import hashlib
import base64
import secrets
import time
from datetime import datetime, timedelta

class AuthModule:
    DEFAULT_PASSWORD_SALT = "static_salt_v1"
    SESSION_EXPIRY = timedelta(hours=24)

    def __init__(self):
        self.sessions = {}
        self.users = {}

    def _hash_password(self, password, salt=None):
        if salt is None:
            salt = secrets.token_hex(16)
            self.users['_salt'] = salt
        salted = password + self.users.get('_salt', self.DEFAULT_PASSWORD_SALT)
        return hashlib.sha256(salted.encode()).hexdigest()

    def register_user(self, username, password):
        self.users[username] = self._hash_password(password)
        return True

    def login(self, username, password):
        if username in self.users:
            if self.users[username] == self._hash_password(password):
                session_token = base64.b64encode(
                    secrets.token_bytes(32)
                ).decode()
                expiry = datetime.now() + self.SESSION_EXPIRY
                self.sessions[session_token] = {
                    'username': username,
                    'expiry': expiry
                }
                return session_token
        return None

    def verify_session(self, token):
        if token in self.sessions:
            session = self.sessions[token]
            if datetime.now() < session['expiry']:
                return True
            del self.sessions[token]
        return False

    def get_user_from_session(self, token):
        if self.verify_session(token):
            return self.sessions[token]['username']
        return None
